"use client";
import { useState } from "react";

import { cn } from "@/lib/utils";

import type { StepperProps, StepDef, StepStatus } from "./stepper.types";

const CheckIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <polyline points="20 6 9 17 4 12" />
  </svg>
);
const ErrorIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <line x1="18" y1="6" x2="6" y2="18" />
    <line x1="6" y1="6" x2="18" y2="18" />
  </svg>
);

function resolveStatus(step: StepDef, idx: number, active: number): StepStatus {
  if (step.status) return step.status;
  if (idx < active) return "completed";
  if (idx === active) return "active";
  return "upcoming";
}

const CIRCLE_STATUS_CLS: Record<StepStatus, string> = {
  upcoming: "border-rule bg-base text-faint",
  active: "border-patina bg-patina-soft text-patina",
  completed: "border-patina bg-patina text-patina-fg",
  error: "border-danger bg-danger-soft text-danger",
};

const LABEL_STATUS_CLS: Record<StepStatus, string> = {
  upcoming: "text-faint",
  active: "text-patina",
  completed: "text-foreground",
  error: "text-danger",
};

function CircleContent({ status, num }: { status: StepStatus; num: number }) {
  if (status === "completed")
    return (
      <span className="[&>svg]:w-[14px] [&>svg]:h-[14px]">
        <CheckIcon />
      </span>
    );
  if (status === "error")
    return (
      <span className="[&>svg]:w-[14px] [&>svg]:h-[14px]">
        <ErrorIcon />
      </span>
    );
  return <>{num + 1}</>;
}

// achado real: círculo clicável era <div onClick> sem alternativa de teclado nenhuma —
// mesma categoria já corrigida em PinBoard/Resizable/CardStack nesta auditoria. <button>
// real dá Enter/Space de graça, sem precisar de onKeyDown manual
function StepCircle({
  status,
  idx,
  label,
  clickable,
  onActivate,
}: {
  status: StepStatus;
  idx: number;
  label: string;
  clickable: boolean;
  onActivate: (idx: number) => void;
}) {
  const interactive = clickable && status === "completed";
  const circleClassName = cn(
    "w-9 h-9 rounded-full border-2 flex items-center justify-center text-body-callout font-bold shrink-0 relative z-[1] transition-[border-color,background,color] duration-[200ms]",
    CIRCLE_STATUS_CLS[status],
    interactive && "cursor-pointer focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-patina"
  );

  if (interactive) {
    return (
      <button
        type="button"
        className={circleClassName}
        onClick={() => onActivate(idx)}
        aria-label={`Go to step ${idx + 1}: ${label}`}
      >
        <CircleContent status={status} num={idx} />
      </button>
    );
  }
  return (
    <div className={circleClassName}>
      <CircleContent status={status} num={idx} />
    </div>
  );
}

export function Stepper({
  steps,
  activeStep,
  defaultStep = 0,
  onStepChange,
  orientation = "horizontal",
  clickable = false,
  className,
  children,
}: StepperProps) {
  const isControlled = activeStep !== undefined;
  const [internal, setInternal] = useState(defaultStep);
  const current = isControlled ? activeStep! : internal;

  function goTo(idx: number) {
    if (!isControlled) setInternal(idx);
    onStepChange?.(idx);
  }

  if (orientation === "vertical") {
    return (
      <div role="list" className={cn("flex flex-col w-full", className)}>
        {steps.map((step, idx) => {
          const status = resolveStatus(step, idx, current);
          const isLast = idx === steps.length - 1;
          return (
            <div
              key={idx}
              role="listitem"
              aria-current={status === "active" ? "step" : undefined}
              className={cn("flex gap-(--spacing-lg) relative", !isLast && "pb-(--spacing-xl)")}
            >
              {!isLast && (
                <div
                  className={cn(
                    "absolute left-[1.0625rem] top-9 bottom-0 w-[2px] transition-[background] duration-[300ms]",
                    status === "completed" ? "bg-patina" : "bg-rule"
                  )}
                />
              )}
              <StepCircle status={status} idx={idx} label={step.label} clickable={clickable} onActivate={goTo} />
              <div className="flex-1 pt-(--spacing-2xs)">
                <p
                  className={cn(
                    "text-body-callout font-semibold transition-[color] duration-[200ms] m-0",
                    LABEL_STATUS_CLS[status]
                  )}
                >
                  {step.label}
                  {step.optional && <span className="font-normal text-faint"> (optional)</span>}
                </p>
                {step.description && (
                  <p className="text-body-callout text-faint mt-(--spacing-3xs) m-0">{step.description}</p>
                )}
                {status === "active" && step.content && <div className="mt-(--spacing-md)">{step.content}</div>}
              </div>
            </div>
          );
        })}
        {children && <div className="mt-(--spacing-lg)">{children}</div>}
      </div>
    );
  }

  const activeStepDef = steps[current];

  return (
    <div className={cn("flex flex-col w-full", className)}>
      <div role="list" className="flex items-start gap-0 mb-(--spacing-2xl)">
        {steps.map((step, idx) => {
          const status = resolveStatus(step, idx, current);
          const isLast = idx === steps.length - 1;
          return (
            <div
              key={idx}
              role="listitem"
              aria-current={status === "active" ? "step" : undefined}
              className={cn(
                "flex flex-col items-center flex-1 relative",
                !isLast &&
                  "after:content-[''] after:absolute after:top-[1.125rem] after:left-[calc(50%+1.125rem)] after:right-[calc(-50%+1.125rem)] after:h-[2px] after:transition-[background] after:duration-[300ms]",
                !isLast && (status === "completed" ? "after:bg-patina" : "after:bg-rule")
              )}
            >
              <StepCircle status={status} idx={idx} label={step.label} clickable={clickable} onActivate={goTo} />
              {/* mt-[0.4rem] (6.4px): sem match exato na escala de spacing (entre xs e sm) */}
              <span
                className={cn(
                  "text-body-caption font-semibold mt-[0.4rem] text-center transition-[color] duration-[200ms]",
                  LABEL_STATUS_CLS[status]
                )}
              >
                {step.label}
                {step.optional && <span className="font-normal text-faint"> *</span>}
              </span>
              {step.description && (
                <span className="text-body-caption text-faint text-center mt-(--spacing-3xs)">{step.description}</span>
              )}
            </div>
          );
        })}
      </div>
      {activeStepDef?.content && <div className="w-full">{activeStepDef.content}</div>}
      {children}
    </div>
  );
}

export function useStepper(totalSteps: number, initial = 0) {
  const [step, setStep] = useState(initial);
  return {
    step,
    isFirst: step === 0,
    isLast: step === totalSteps - 1,
    next: () => setStep((s) => Math.min(s + 1, totalSteps - 1)),
    prev: () => setStep((s) => Math.max(s - 1, 0)),
    goTo: setStep,
    reset: () => setStep(0),
  };
}

import type React from "react";

export type StepperOrientation = "horizontal" | "vertical";
export type StepStatus = "upcoming" | "active" | "completed" | "error";

export interface StepDef {
  label: string;
  description?: string;
  content?: React.ReactNode;
  optional?: boolean;
  status?: StepStatus;
}

export interface StepperProps {
  steps: StepDef[];
  activeStep?: number;
  defaultStep?: number;
  onStepChange?: (step: number) => void;
  orientation?: StepperOrientation;
  clickable?: boolean;
  className?: string;
  children?: React.ReactNode;
}
